import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'3yIHMxCIF9QgqjNOrSXC',titulo:'Colchão Casal Emma Original 138x188cm 3 Camadas de Espuma, Embalado à Vácuo, Suporte para Coluna, Alta Respirabilidade, Capa Lavável',listing:'MLB2171368181'},{id:'41xTWhFAFp82XNFL5V87',titulo:'Rastreador GPS Veicular 4G com App em Tempo Real | Ideal para Frotas, Carro, Moto, Caminhão e Veículos Elétricos',listing:'MLB4742623935'},{id:'4DLJoHbBXNFffpz3DNcv',titulo:'Kit 10 Pote De Vidro Marmita Hermético 640ml Freezer Fitness Rishon'}];
test('triagem51 preserva operação e afiliados e não aplica correção a outra identidade',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{id:'outro'},...(r.listing?[{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}]:[])])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Emma mantém casal e não garante efeito clínico, conforto ou garantia de outro canal',()=>{const x=correctProductData(rows[0]);assert.match(x.titulo,/138 × 188 cm/);assert.match(x.comentario,/não é apresentada como garantia de aliviar dor/);assert.match(x.comentario,/não presumimos que condições de outro canal/);assert.doesNotMatch(x.pros,/coluna|alivia|garant|ideal|terap|cura/i);});
test('rastreador não confirma compatibilidade universal ou serviço gratuito',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/não comprova compatibilidade com cada instalação/);assert.match(x.comentario,/não é garantia de serviço gratuito permanente/);assert.match(x.comentario,/Não identificamos.*código exato/);assert.doesNotMatch(x.pros,/ideal|universal|gratuito|ininterrupto|recupera/i);});
test('Rishon não converte freezer em resistência térmica ou vedação testada',()=>{const x=correctProductData(rows[2]);assert.equal(x.titulo,rows[2].titulo);assert.match(x.comentario,/não confirma, por si só, uso em forno/);assert.match(x.comentario,/não inferimos tipo de vidro, temperatura/);assert.doesNotMatch(x.pros,/eficiente|resistente|borossilicato|garant|forno|micro-ondas|°/i);});
